 "content": "def transform(grid):
    g = [row[:] for row in grid]
    bg = grid[0][0]
    fg = next(c for row in grid for c in row if c != bg)
    # Find the longest row; recolor background gaps between the two parts
    # of that bar, extending the gap vertically until the lower cap.
    bar_r = max(range(len(grid)), key=lambda r: sum(x == fg for x in grid[r]))
    cols = [c for c,x in enumerate(grid[bar_r]) if x == fg]
    gaps=[]
    for a,b in zip(cols, cols[1:]):
        if b-a > 1:
            gaps.extend(range(a+1,b))
    for c in gaps:
        for r in range(bar_r, len(grid)):
            if grid[r][c] == fg:
                break
            # Only extend through rows where this position is part of the
            # vertical corridor bounded by nearby foreground structure.
            if sum(grid[r][j] == fg for j in range(max(0,c-1),min(len(grid[r]),c+2))) >= 2:
                g[r][c] = 4
    return g
